import React, { useState, useEffect } from "react";
import axios from "axios";
import ProductCard from "./ProductCard";
import SearchBar from "./SearchBar";
import {
  Grid,
  Select,
  MenuItem,
  InputLabel,
  FormControl,
  Typography,
  Box,
  Paper,
  Chip,
  InputAdornment,
  TextField,
  Divider,
  Container
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import FilterAltIcon from "@mui/icons-material/FilterAlt";
import CakeIcon from "@mui/icons-material/Cake";
import LocalCafeIcon from "@mui/icons-material/LocalCafe";

const ProductList = () => {
  const [products, setProducts] = useState([]);
  const [searchText, setSearchText] = useState("");
  const [category, setCategory] = useState("all");
  
  useEffect(() => {
    axios
      .get("http://localhost:3000/cakes")
      .then((response) => setProducts(response.data))
      .catch((error) => console.error("Error fetching data:", error));
  }, []);
  
  const handleCategoryChange = (event) => {
    setCategory(event.target.value);
  };
  
  const handleSearchChange = (event) => {
    setSearchText(event.target.value);
  };

  const categoryOptions = [
    { value: "all", label: "All Products", icon: <FilterAltIcon /> },
    { value: "cakes", label: "Cakes", icon: <CakeIcon /> },
    { value: "cookies", label: "Cookies", icon: <LocalCafeIcon /> },
    { value: "brownies", label: "Brownies", icon: <LocalCafeIcon /> }
  ];

  const filteredProducts = products.filter((product) => {
    const matchesSearch = product.name.toLowerCase().includes(searchText.toLowerCase());
    const matchesCategory = category === "all" || product.category.toLowerCase() === category.toLowerCase();
    return matchesSearch && matchesCategory;
  });
  
  return (
    <Container maxWidth="xl">
      <Box sx={{ padding: 4 }}>
        <Typography 
          variant="h4" 
          gutterBottom 
          sx={{ 
            fontWeight: 600, 
            textAlign: "center",
            marginBottom: 4,
            color: "#d32f2f" 
          }}
        >
          Choose Your Treats 🍰
        </Typography>
        
        {/* Enhanced Filter Section */}
        <Paper 
          elevation={3} 
          sx={{ 
            padding: 3, 
            marginBottom: 4, 
            borderRadius: 2,
            background: "linear-gradient(to right, #fff8e1, #fff)"
          }}
        >
          <Box sx={{ display: "flex", flexDirection: {xs: "column", md: "row"}, gap: 2, alignItems: "center" }}>
            {/* Search Bar */}
            <Box sx={{ flexGrow: 1 }}>
              <TextField
                fullWidth
                value={searchText}
                onChange={handleSearchChange}
                placeholder="Search for treats..."
                variant="outlined"
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon color="primary" />
                    </InputAdornment>
                  ),
                  sx: { borderRadius: 2 }
                }}
              />
            </Box>
            
            <Divider orientation="vertical" flexItem sx={{ display: {xs: "none", md: "block"} }} />
            
            {/* Category Filter */}
            <Box sx={{ minWidth: 200 }}>
              <FormControl fullWidth>
                <InputLabel id="category-select-label">Category</InputLabel>
                <Select
                  labelId="category-select-label"
                  value={category}
                  label="Category"
                  onChange={handleCategoryChange}
                  sx={{ 
                    borderRadius: 2,
                    "& .MuiSelect-select": { display: "flex", alignItems: "center", gap: 1 }
                  }}
                >
                  {categoryOptions.map((option) => (
                    <MenuItem key={option.value} value={option.value} sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                      {option.icon}
                      {option.label}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Box>
          </Box>
          
          {/* Active filters display */}
          <Box sx={{ display: "flex", gap: 1, marginTop: 2, flexWrap: "wrap" }}>
            {searchText && (
              <Chip 
                label={`Search: ${searchText}`} 
                onDelete={() => setSearchText("")}
                color="primary"
                size="small"
              />
            )}
            {category !== "all" && (
              <Chip 
                label={`Category: ${category}`} 
                onDelete={() => setCategory("all")}
                color="secondary"
                size="small"
              />
            )}
          </Box>
        </Paper>
        
        {/* Results summary */}
        <Box sx={{ marginBottom: 2 }}>
          <Typography variant="body1" color="text.secondary">
            Showing {filteredProducts.length} {filteredProducts.length === 1 ? "item" : "items"}
          </Typography>
        </Box>
        
        {/* Product Grid */}
        <Grid container spacing={3} justifyContent="center">
          {filteredProducts.map((product, index) => (
            <Grid item key={product.id || index} xs={12} sm={6} md={4} lg={3}>
              <ProductCard product={product} />
            </Grid>
          ))}
          
          {filteredProducts.length === 0 && (
            <Box sx={{ padding: 4, textAlign: "center", width: "100%" }}>
              <Typography variant="h6" color="text.secondary">
                No products found matching your criteria.
              </Typography>
            </Box>
          )}
        </Grid>
      </Box>
    </Container>
  );
};

export default ProductList;
